import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(g):
    H=len(g); W=len(g[0]); g=[row[:] for row in g]
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    line=None; sh=[]
    for r in range(H):
        if len(set(g[r]))==1 and g[r][0]!=bg:
            line=r
        else:
            for c in range(W):
                if g[r][c]!=bg: sh.append((r,c))
    out=[row[:] for row in g]
    # components in top-to-bottom order; 8-row appended after the LAST component
    comps=[]
    if line is not None: comps.append(('L',line))
    if sh:
        rs=[p[0] for p in sh]; comps.append(('S',min(rs)))
    for name,pos in comps:
        if name=='L': out[pos]=[g[pos][:]]  # keep
        else: pass
    if 'S' in [n for n,_ in comps]:
        mx=max(p[0] for p in sh)
        far=mx+1
        while far<H-1: far+=1
        far=mx+1
        if 0<=far<H: out[far]=[8]*W
    elif 'L' in [n for n,_ in comps]:
        far=line+1
        if 0<=far<H: out[far]=[8]*W
    return out
